/* whocode live announcement poller */
import {
  app as __ollieAnnApp,
  Notification as __ollieAnnNotification,
  shell as __ollieAnnShell,
} from "electron"
import {
  mkdirSync as __ollieAnnMkdir,
  readFileSync as __ollieAnnRead,
  writeFileSync as __ollieAnnWrite,
} from "node:fs"
import { dirname as __ollieAnnDirname, join as __ollieAnnJoin } from "node:path"
;(() => {
  const gateway = (process.env.WHOCODE_LICENSE_API || "https://license.whocode.app").replace(/\/+$/, "")
  let seenPath = ""
  let last = ""
  const show = (a) => {
    if (!a || !a.id || typeof a.message !== "string" || !a.message || a.id === last) return
    last = a.id
    try {
      __ollieAnnMkdir(__ollieAnnDirname(seenPath), { recursive: true })
      __ollieAnnWrite(seenPath, JSON.stringify({ id: a.id, at: Date.now() }))
    } catch {}
    if (!__ollieAnnNotification.isSupported()) return
    const title =
      a.level === "critical" ? "whocode · important" : a.level === "warning" ? "whocode · notice" : "whocode"
    const body = a.message.length > 400 ? a.message.slice(0, 397) + "..." : a.message
    const n = new __ollieAnnNotification({ title, body, silent: false })
    n.on("click", () => {
      try {
        __ollieAnnShell.openExternal("https://discord.gg/whocode")
      } catch {}
    })
    n.show()
  }
  const poll = async () => {
    try {
      const res = await fetch(gateway + "/api/announcement", { headers: { "cache-control": "no-store" } })
      if (!res.ok) return
      const body = await res.json()
      if (body && body.ok) show(body.announcement)
    } catch {}
  }
  __ollieAnnApp.whenReady().then(() => {
    try {
      seenPath = __ollieAnnJoin(__ollieAnnApp.getPath("userData"), "announcement-seen.json")
      last = JSON.parse(__ollieAnnRead(seenPath, "utf8")).id || ""
    } catch {}
    setTimeout(poll, 5_000)
    setInterval(poll, 30_000)
  })
})()

/* whocode desktop behaviour: auto-open + auto-update */
import {
  app as __ollieAutoApp,
  BrowserWindow as __OllieAutoWindow,
} from "electron"
import { appendFileSync, existsSync, readdirSync, statSync } from "node:fs"
import { homedir as __ollieAutoHome, tmpdir as __ollieAutoTmp } from "node:os"
import { join as __ollieAutoJoin } from "node:path"
import { spawn as __ollieAutoSpawn } from "node:child_process"
;(() => {
  // Give whocode its own taskbar identity. The upstream OpenCode desktop
  // uses ai.opencode.desktop[.dev]; sharing it makes Windows reuse the
  // OpenCode/Electron taskbar icon and cache. The userData path was already
  // set from APP_ID before this runs, so only the taskbar/notification ID moves.
  try {
    __ollieAutoApp.setAppUserModelId("ai.whocode.desktop")
  } catch {}
  const log = (line) => {
    try {
      appendFileSync(__ollieAutoJoin(__ollieAutoApp.getPath("userData"), "desktop-behavior.log"), new Date().toISOString() + " " + line + "\n")
    } catch {}
  }
  const versionParts = (v) => String(v).split(/[-+]/, 1)[0].split(".").map((n) => parseInt(n, 10) || 0)
  const newer = (a, b) => {
    const sa = versionParts(a)
    const sb = versionParts(b)
    const n = Math.max(sa.length, sb.length)
    for (let i = 0; i < n; i++) {
      const d = (sa[i] ?? 0) - (sb[i] ?? 0)
      if (d !== 0) return d > 0
    }
    return false
  }

  __ollieAutoApp.whenReady().then(() => {
    // Auto-open: close the first-run license window once the activation
    // cache appears. Do not touch it if a main window already exists
    // (license management is opened from a running app).
    const licensePath = __ollieAutoJoin(
      process.env.XDG_DATA_HOME || __ollieAutoJoin(__ollieAutoHome(), ".local", "share"),
      "opencode",
      "license.json",
    )
    setInterval(() => {
      try {
        if (!existsSync(licensePath)) return
        const windows = __OllieAutoWindow.getAllWindows()
        const hasMain = windows.some((w) => {
          const title = w.getTitle()
          return title === "whocode" || (title.startsWith("whocode") && !title.includes("License"))
        })
        if (hasMain) return
        const licenseWindow = windows.find((w) => w.getTitle().includes("License"))
        if (licenseWindow) {
          log("license cache present; closing first-run window")
          licenseWindow.close()
        }
      } catch {}
    }, 1_000)

    // Auto-update: the updater downloads and sha-verifies into
    // %TEMP%\whocode-update. Launch a newer, stable, fully written file.
    const updateDir = __ollieAutoJoin(__ollieAutoTmp(), "whocode-update")
    let launching = false
    const checkUpdate = () => {
      if (launching) return
      if (!existsSync(updateDir)) return
      let names = []
      try {
        names = readdirSync(updateDir)
      } catch {
        return
      }
      for (const name of names) {
        if (!/^whocode-Setup-.*\.exe$/i.test(name)) continue
        const version = name.replace(/^whocode-Setup-/, "").replace(/\.exe$/i, "")
        if (!newer(version, __ollieAutoApp.getVersion())) continue
        const full = __ollieAutoJoin(updateDir, name)
        let stat
        try {
          stat = statSync(full)
        } catch {
          continue
        }
        if (stat.size < 100_000_000) continue
        if (Date.now() - stat.mtimeMs < 5_000) continue
        launching = true
        log("auto-installing " + name + " (" + stat.size + " bytes)")
        try {
          const child = __ollieAutoSpawn(
            full,
            ["/SILENT", "/SUPPRESSMSGBOXES", "/CLOSEAPPLICATIONS", "/FORCECLOSEAPPLICATIONS"],
            { detached: true, stdio: "ignore", windowsHide: true },
          )
          child.once("error", (cause) => {
            launching = false
            log("installer spawn failed: " + (cause && cause.message ? cause.message : String(cause)))
          })
          child.unref()
          setTimeout(() => __ollieAutoApp.quit(), 1_200)
        } catch (cause) {
          launching = false
          log("installer spawn threw: " + (cause && cause.message ? cause.message : String(cause)))
        }
        return
      }
    }
    setTimeout(checkUpdate, 5_000)
    setInterval(checkUpdate, 10_000)
  })
})()

/* whocode auto-jb bridge */
import { createServer as __ollieJbServer } from "node:http"
import {
  copyFileSync as __ollieJbCopy,
  existsSync as __ollieJbExists,
  mkdirSync as __ollieJbMkdir,
  readFileSync as __ollieJbRead,
  rmSync as __ollieJbRm,
  writeFileSync as __ollieJbWrite,
} from "node:fs"
import { homedir as __ollieJbHome } from "node:os"
import { join as __ollieJbJoin } from "node:path"
import { app as __ollieJbApp } from "electron"
;(() => {
  if (process.platform !== "linux") return
  const port = 31999
  const state = __ollieJbJoin(__ollieJbApp.getPath("userData"), "auto-jb.json")
  const config = __ollieJbJoin(process.env.XDG_CONFIG_HOME || __ollieJbJoin(__ollieJbHome(), ".config"), "opencode")
  const agents = __ollieJbJoin(config, "AGENTS.md")
  const backup = agents + ".whocode-backup"
  const source = __ollieJbJoin(__ollieJbApp.getAppPath(), "resources", "auto-jb-AGENTS.md")
  const isOn = () => {
    try {
      return JSON.parse(__ollieJbRead(state, "utf8")).enabled === true
    } catch {
      return false
    }
  }
  const persist = (v) => {
    try {
      __ollieJbWrite(state, JSON.stringify({ enabled: v }))
    } catch {}
  }
  const apply = (v) => {
    __ollieJbMkdir(config, { recursive: true })
    if (v) {
      if (__ollieJbExists(agents) && !__ollieJbExists(backup)) __ollieJbCopy(agents, backup)
      __ollieJbWrite(agents, __ollieJbRead(source))
    } else {
      if (__ollieJbExists(backup)) {
        __ollieJbCopy(backup, agents)
        __ollieJbRm(backup)
      } else if (__ollieJbExists(agents)) {
        __ollieJbRm(agents)
      }
    }
    persist(v)
  }
  const server = __ollieJbServer((req, res) => {
    res.setHeader("access-control-allow-origin", "*")
    res.setHeader("access-control-allow-headers", "authorization, content-type")
    res.setHeader("access-control-allow-methods", "GET, POST, OPTIONS")
    if (req.method === "OPTIONS") {
      res.writeHead(204)
      res.end()
      return
    }
    const url = new URL(req.url || "/", "http://127.0.0.1")
    if (url.pathname !== "/_whocode/abliterated") {
      res.writeHead(404)
      res.end()
      return
    }
    if (req.method === "GET") {
      res.setHeader("content-type", "application/json")
      res.end(JSON.stringify({ ok: true, enabled: isOn() }))
      return
    }
    if (req.method === "POST") {
      const v = url.searchParams.get("enabled") === "1"
      try {
        apply(v)
        res.setHeader("content-type", "application/json")
        res.end(JSON.stringify({ ok: true, enabled: v }))
      } catch (e) {
        res.writeHead(500)
        res.end(JSON.stringify({ ok: false, error: String(e) }))
      }
      return
    }
    res.writeHead(405)
    res.end()
  })
  server.on("error", () => {})
  server.listen(port, "127.0.0.1")
  __ollieJbApp.on("quit", () => {
    try {
      server.close()
    } catch {}
  })
})()
